    const url = scalekit.getAuthorizationUrl(
      redirectUri,
      {
        scopes: ['openid', 'profile', 'email', 'offline_access']
      }
    );
    res.redirect(url);
  } catch (error) {
    res.status(500).send('Error generating auth url');
  }
});

